css:
body :where([data-bz-node="lk"]) .bz-block{padding:0}
body :where([data-bz-node="lk"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="lk"]>.bz-container{padding-inline:0}

body [data-bz-node="lk"]{background:var(--paper);padding:96px 0}
body [data-bz-node="lk"]>.bz-container{max-width:var(--container)}
body [data-bz-node="lk-h"] .bz-eyebrow{font:700 10.5px/1.4 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:#6b6b6a;margin:0 0 14px}
body [data-bz-node="lk-h"] h2{font:700 36px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="lk-grid"]{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:40px;align-items:stretch}
body [data-bz-node="lk-grid"]>.bz-col{grid-column:auto}
body [data-bz-node^="lk-card-"]{display:flex;flex-direction:column;background:#fff;border:1px solid #e4e4e2;padding:28px 26px 26px;box-sizing:border-box}
body [data-bz-node^="lk-title-"] h3{font:700 15px/1.3 var(--font-heading);letter-spacing:.01em;text-transform:uppercase;color:var(--ink);margin:0 0 14px}
body [data-bz-node^="lk-text-"] .bz-text{max-width:none;margin-bottom:22px}
body [data-bz-node^="lk-text-"] p{font:400 12.5px/1.7 var(--font-body);color:#555;margin:0}
body [data-bz-node^="lk-link-"]{margin-top:auto;padding-top:22px}
body [data-bz-node^="lk-link-"] .bz-btns{margin:0}
body [data-bz-node^="lk-link-"] .bz-btn{padding:0;border:0;background:none;color:var(--ink);font:700 10.5px/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;text-decoration:none;gap:10px;height:auto;min-height:0}
body [data-bz-node^="lk-link-"] .bz-btn::after{content:"";width:13px;height:13px;background:currentColor;-webkit-mask:url(/icons/arrow-right.svg) center/13px no-repeat;mask:url(/icons/arrow-right.svg) center/13px no-repeat}
body [data-bz-node^="lk-link-"] .bz-btn:hover{color:var(--accent)}
@media (max-width:1100px){body [data-bz-node="lk"]{padding:64px 24px}body [data-bz-node="lk-h"] h2{font-size:30px}body [data-bz-node="lk-grid"]{grid-template-columns:repeat(2,1fr)}}
@media (max-width:640px){body [data-bz-node="lk"]{padding:48px 20px}body [data-bz-node="lk-h"] h2{font-size:26px}body [data-bz-node="lk-grid"]{grid-template-columns:1fr;gap:14px;margin-top:28px}}
